-- Generated by tools/build_data.py. 876 exercises from free-exercise-db (public domain) and 5 built in.
-- One line each: id | domain region load measure source | equipment | main muscle | name (when it differs from the id).
insert into public.exercises (id, name, domain, source, equipment, primary_muscles, region, load_type, measure)
select p[1],
       coalesce(nullif(p[5], ''), replace(p[1], '_', ' ')),
       case substr(p[2], 1, 1) when 's' then 'strength' when 'm' then 'mobility' else 'cardio' end,
       case substr(p[2], 5, 1) when 'b' then 'builtin' else 'free-exercise-db' end,
       nullif(p[3], ''),
       case when coalesce(p[4], '') = '' then '{}'::text[] else array[p[4]] end,
       case substr(p[2], 2, 1) when 'u' then 'upper' when 'l' then 'lower' when 'c' then 'core' end,
       case substr(p[2], 3, 1) when 'b' then 'bodyweight' else 'external' end,
       case substr(p[2], 4, 1) when 's' then 'seconds' else 'reps' end
from (select string_to_array(line, '|') as p from regexp_split_to_table($seed$
